/bin/zsh -lc "python3 -B -c 'from math import factorial
from itertools import permutations, combinations
for n in range(3, 9):
    patterns = set()
    pairs = list(combinations(range(1, n + 1), 2))
    for p in permutations(range(1, n + 1)):
        positions = {v: i for i, v in enumerate(p)}
        patterns.add(tuple(positions[u] < positions[v] for u, v in pairs))
    required = (factorial(n) - 1).bit_length()
    print(f\"n={n}: distinct order-answer patterns={len(patterns)}, messages={2 ** (n - 1)}, minimum bits={required}\")'"

